  const baseUrl = await startReplayServer((key, bytes) =>
    key === LATEST_ARTIFACT_KEY
      ? { bytes: Buffer.from(JSON.stringify({ ...JSON.parse(bytes.toString("utf8")), indexSha256: "b".repeat(64) })) }
      : undefined,
