import { expect, test } from "vitest";
import {
  frame,
  getMockGPUDeviceInstrumentation,
  init,
  target,
} from "vgpu/mock";
import {
  createRadiance,
  destroyRadiance,
  setRadianceScene,
  setRadianceTime,
  type Radiance,
} from "./radiance";

test("the radiance emitter starts at time zero and retains animation when its scene is rebound", async () => {
  const gpu = await init();
  let radiance: Radiance | undefined;
  try {
    const scene = target(gpu, { size: [1000, 600], format: "rgba16float" });
    radiance = createRadiance(gpu, scene.size);
    setRadianceScene(radiance, scene);
    await radiance.effects.emitter.compile(radiance.emitter);
    frame(gpu, (current) =>
      current.pass({ target: radiance!.emitter }, (pass) =>
        pass.draw(radiance!.effects.emitter)
      )
    );
    await gpu.settled();

    const buffers = new Set<GPUBuffer>();
    for (const descriptor of getMockGPUDeviceInstrumentation(gpu.device.gpu)
      .createBindGroupDescriptors)
      for (const { resource } of descriptor.entries)
        if ("buffer" in resource && resource.buffer.label.endsWith(".params"))
          buffers.add(resource.buffer);
    expect(buffers.size).toBe(1);
    const buffer = [...buffers][0]!;
    if (
      !("__vgpuMockBytes" in buffer) ||
      !(buffer.__vgpuMockBytes instanceof Uint8Array)
    )
      throw new Error(
        "The public mock backend did not expose packed buffer bytes"
      );
    const bytes = buffer.__vgpuMockBytes;
    const values = new Float32Array(
      bytes.buffer,
      bytes.byteOffset,
      bytes.byteLength / 4
    );
    expect(radiance.emitter.size).toEqual([480, 288]);
    expect([...values]).toEqual([0, Math.fround(480 / 288)]);

    setRadianceTime(radiance, 7.25);
    setRadianceScene(
      radiance,
      target(gpu, { size: [500, 500], format: "rgba16float" })
    );
    expect([...values]).toEqual([7.25, Math.fround(480 / 288)]);
  } finally {
    if (radiance) destroyRadiance(radiance);
    gpu.dispose();
  }
});

import { describe, expect, it } from "vitest";
import { createSwitchQueue } from "./scheduling";

function deferred() {
  let resolve!: () => void;
  let reject!: (error: unknown) => void;
  const promise = new Promise<void>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

const settle = async () => {
  for (let i = 0; i < 4; i += 1) await Promise.resolve();
};

describe("createSwitchQueue", () => {
  it("runs one transition at a time", async () => {
    const started: string[] = [];
    const gate = deferred();
    const queue = createSwitchQueue<string>(() => {});

    queue.push("midas", (value) => {
      started.push(value);
      return gate.promise;
    });
    queue.push("dav2", (value) => {
      started.push(value);
      return Promise.resolve();
    });
    await settle();

    // The second choice waits for the first session to finish releasing.
    expect(started).toEqual(["midas"]);
    gate.resolve();
    await settle();
    expect(started).toEqual(["midas", "dav2"]);
  });

  it("drops choices that were superseded before they started", async () => {
    const started: string[] = [];
    const gate = deferred();
    const queue = createSwitchQueue<string>(() => {});

    queue.push("a", (value) => {
      started.push(value);
      return gate.promise;
    });
    queue.push("b", (value) => {
      started.push(value);
      return Promise.resolve();
    });
    queue.push("c", (value) => {
      started.push(value);
      return Promise.resolve();
    });
    gate.resolve();
    await settle();

    // 'b' is never loaded: clicking through the list must not download every
    // model on the way to the one wanted.
    expect(started).toEqual(["a", "c"]);
  });

  it("aborts obsolete active work and starts only the newest replacement after it settles", async () => {
    const started: string[] = [];
    const aborted: string[] = [];
    const queue = createSwitchQueue<string>(() => {});

    queue.push("slow", (value, signal) => {
      started.push(value);
      return new Promise<void>((resolve) => {
        signal.addEventListener("abort", () => {
          aborted.push(value);
          resolve();
        });
      });
    });
    queue.push("skipped", (value) => {
      started.push(value);
      return Promise.resolve();
    });
    queue.push("latest", (value) => {
      started.push(value);
      return Promise.resolve();
    });
    await settle();

    expect(aborted).toEqual(["slow"]);
    expect(started).toEqual(["slow", "latest"]);
  });

  it("reports a failure and keeps accepting later switches", async () => {
    const errors: unknown[] = [];
    const started: string[] = [];
    const queue = createSwitchQueue<string>((error) => errors.push(error));

    queue.push("broken", () =>
      Promise.reject(new Error("session create failed"))
    );
    await settle();
    expect((errors[0] as Error).message).toBe("session create failed");

    queue.push("recovered", (value) => {
      started.push(value);
      return Promise.resolve();
    });
    await settle();
    expect(started).toEqual(["recovered"]);
  });

  it("exposes the in-flight transition so callers can drain before disposing", async () => {
    const gate = deferred();
    const queue = createSwitchQueue<string>(() => {});
    expect(queue.busy).toBe(false);

    queue.push("midas", () => gate.promise);
    expect(queue.busy).toBe(true);
    const active = queue.active;
    expect(active).toBeInstanceOf(Promise);

    gate.resolve();
    await active;
    await settle();
    expect(queue.busy).toBe(false);
  });
});

